public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    // reference: entries {key, val, freq, lastUse}; O(n) per operation
    static int tick;

    static int[] find(List<int[]> l, int k) {
        for (int[] e : l) {
            if (e[0] == k) {
                return e;
            }
        }
        return null;
    }

    static int bGet(List<int[]> l, int k) {
        int[] e = find(l, k);
        if (e == null) {
            return -1;
        }
        e[2]++;
        e[3] = ++tick;
        return e[1];
    }

    static void bPut(List<int[]> l, int cap, int k, int v) {
        if (cap == 0) {
            return;
        }
        int[] e = find(l, k);
        if (e != null) {
            e[1] = v;
            e[2]++;
            e[3] = ++tick;
            return;
        }
        if (l.size() == cap) {
            int[] w = l.get(0);
            for (int[] x : l) {
                if (x[2] < w[2] || (x[2] == w[2] && x[3] < w[3])) {
                    w = x;
                }
            }
            l.remove(w);
        }
        l.add(new int[] {k, v, 1, ++tick});
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        LFUCache c = new LFUCache(2);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
