                    String sai = null;
                    int ops = 0;
                    for (int t = 0; t < 300 && sai == null; t++) {
                        int cap = rnd.nextInt(4);
                        LFUCache x = new LFUCache(cap);
                        List<int[]> l = new ArrayList<int[]>();
                        for (int q = 0; q < 60 && sai == null; q++) {
                            int k = rnd.nextInt(6);
                            ops++;
                            if (rnd.nextBoolean()) {
                                int v = rnd.nextInt(100);
                                x.put(k, v);
                                bPut(l, cap, k, v);
                            } else {
                                int got = x.get(k), want = bGet(l, k);
                                if (got != want) {
