public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        MinStack s = new MinStack();
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("PUSH")) {
                    s.push(n(1));
                } else if (p[0].equals("POP")) {
                    r = String.valueOf(s.pop());
                } else if (p[0].equals("TOP")) {
                    r = String.valueOf(s.top());
                } else if (p[0].equals("MIN")) {
                    r = String.valueOf(s.getMin());
                } else if (p[0].equals("RANDOM")) {
                    Random rnd = new Random(159);
                    String sai = null;
                    int ops = 0;
                    for (int t = 0; t < 200 && sai == null; t++) {
                        MinStack x = new MinStack();
                        List<Integer> l = new ArrayList<Integer>();
                        for (int q = 0; q < 50 && sai == null; q++) {
                            ops++;
                            int op = rnd.nextInt(4);
                            String got, want;
                            if (op == 0 || l.isEmpty()) {
                                int v = rnd.nextInt(21) - 10;
                                x.push(v);
                                l.add(v);
                                got = "";
                                want = "";
                            } else if (op == 1) {
                                got = "" + x.pop();
                                want = "" + l.remove(l.size() - 1);
                            } else if (op == 2) {
                                got = "" + x.top();
                                want = "" + l.get(l.size() - 1);
                            } else {
                                got = "" + x.getMin();
                                want = "" + Collections.min(l);
                            }
                            if (!got.equals(want)) {
                                sai = "operation " + (q + 1) + " on " + l + ": " + got + ", expected " + want;
                            }
                        }
                    }
                    r = ketQua("200 random stacks x 50 operations", ops, sai);
                } else {
                    final Random rnd = new Random(161);
                    final long[] sum = new long[1];
                    r = Kiem.hen("1,000,000 operations + getMin after each", 3000, new Runnable() {
                        public void run() {
                            MinStack x = new MinStack();
                            int size = 0;
                            for (int i = 0; i < 1000000; i++) {
                                if (size == 0 || i % 3 != 0) {
                                    x.push(1000000 - i + rnd.nextInt(1000));
                                    size++;
                                } else {
                                    x.pop();
                                    size--;
                                }
                                sum[0] += x.getMin();
                            }
                        }
                    }) + ", sum " + sum[0];
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r);
        }
    }
}

import java.lang.reflect.Constructor;
