            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    // reference with the same layout, O(n) per remove
    static class Ref {
        List<Integer> a = new ArrayList<Integer>();
        Random rnd;

        Ref(Random rnd) {
            this.rnd = rnd;
        }

        boolean insert(int x) {
            if (a.contains(x)) {
                return false;
            }
            a.add(x);
            return true;
        }

        boolean remove(int x) {
            int i = a.indexOf(x);
            if (i < 0) {
                return false;
            }
            a.set(i, a.get(a.size() - 1));
            a.remove(a.size() - 1);
            return true;
        }

        int getRandom() {
            return a.get(rnd.nextInt(a.size()));
        }
    }

