                    s = new RandomizedSet(new Random(n(1)));
                } else if (p[0].equals("INS")) {
                    r = String.valueOf(s.insert(n(1)));
                } else if (p[0].equals("DEL")) {
                    r = String.valueOf(s.remove(n(1)));
                } else if (p[0].equals("RND")) {
