        if (tm == null) {
            tm = new TreeMap<Integer, String>();
            m.put(key, tm);
        }
        tm.put(t, value);
    }

    public String get(String key, int t) {
        TreeMap<Integer, String> tm = m.get(key);
        if (tm == null) {
            return "";
        }
        Map.Entry<Integer, String> e = tm.floorEntry(t); // latest time <= t, O(log n)
        return e == null ? "" : e.getValue();
    }
}

