            x = (x * 6364136223846793005L + 1442695040888963407L);
            a[i] = (int) ((x >>> 33) % bound);
        }
        return a;
    }

    /** A failed call, printed as its message. */
    public static final class Loi {
        private final String text;

        Loi(String text) {
            this.text = text;
        }

        @Override
        public String toString() {
            return text;
        }
    }
}

